ALTER TABLE "copy_agent_setups" ADD CONSTRAINT "copy_agent_setups_ready_check" CHECK ("copy_agent_setups"."state" not in ('ready', 'approval_signing', 'approval_unknown', 'active') or ("copy_agent_setups"."agent_wallet_id" is not null and "copy_agent_setups"."agent_owner_quorum_id" is not null and "copy_agent_setups"."agent_address" is not null and "copy_agent_setups"."agent_address" ~ '^0x[0-9a-f]{40}$' and "copy_agent_setups"."policy_id" is not null and "copy_agent_setups"."policy_fingerprint" is not null and "copy_agent_setups"."policy_fingerprint" ~ '^[0-9a-f]{64}$'));